// The same blink with the STM32 HAL (as generated by STM32CubeIDE, trimmed).
#include "stm32f4xx_hal.h"

int main(void)
{
    HAL_Init();                                 // SysTick at 1 kHz, flash settings
    __HAL_RCC_GPIOA_CLK_ENABLE();
    GPIO_InitTypeDef io = {0};
    io.Pin = GPIO_PIN_5;
    io.Mode = GPIO_MODE_OUTPUT_PP;
    io.Pull = GPIO_NOPULL;
    io.Speed = GPIO_SPEED_FREQ_LOW;
    HAL_GPIO_Init(GPIOA, &io);
    for (;;) {
        HAL_GPIO_TogglePin(GPIOA, GPIO_PIN_5);
        HAL_Delay(500);                         // ms, from the SysTick counter
    }
}
